.marker-cluster {
	background-clip: padding-box;
	border-radius: 20px;
    animation: border-pulse 2s infinite;
	}
.marker-cluster div {
	width: 30px;
	height: 30px;
	margin-left: 5px;
	margin-top: 5px;

	text-align: center;
	border-radius: 15px;
	font: 12px var(--system-ui);
	font-weight: bolder;
	color: black;
	}
